<script setup lang="ts">const route=useRoute();const shop=useShop();const q=ref(typeof route.query.q==='string'?route.query.q:'');watch(()=>route.query.q,v=>q.value=typeof v==='string'?v:'');const results=computed(()=>shop.products.filter(p=>!q.value||`${p.name} ${p.category} ${p.gender} ${p.description}`.toLowerCase().includes(q.value.toLowerCase())))</script><template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-12"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">Find your next favorite</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">Search<span class="text-brand">.</span></h1><form class="my-7 flex max-w-2xl gap-2" @submit.prevent="navigateTo({path:'/search',query:q?{q}: {}})"><input v-model="q" autofocus class="min-w-0 flex-1 rounded-full border border-gray-200 px-5 py-4 text-sm outline-none focus:border-brand" placeholder="Search tees, bags, everyday essentials..."><button class="rounded-full bg-ink px-6 text-xs font-bold uppercase tracking-wider text-white">Search</button></form><p class="mb-5 text-sm text-gray-500">{{ results.length }} result(s){{ q?' for “'+q+'”':'' }}</p><ProductGrid :products="results"/></div></template>
